.\[\&\>div\.ov-container\]\:pb-28>div.ov-container{padding-bottom:calc(var(--spacing) * 28)}
@media (min-width:48rem){.md\:\[\&\>div\.ov-container\]\:pb-36>div.ov-container{padding-bottom:calc(var(--spacing) * 36)}
.ov-measure{max-width:var(--ov-measure)}
.ov-display{letter-spacing:-.035em;font-size:clamp(2.35rem,1.45rem + 4vw,4.75rem);line-height:1.02}
.ov-display,.ov-h1{font-family:var(--font-display);font-weight:800}
.ov-h1{letter-spacing:-.03em;font-size:clamp(2.1rem,1.5rem + 2.7vw,3.75rem);line-height:1.06}
.ov-h2{letter-spacing:-.028em;font-size:clamp(1.75rem,1.3rem + 1.9vw,3rem);font-weight:800;line-height:1.1}
.ov-h2,.ov-h3{font-family:var(--font-display)}
.ov-h3{letter-spacing:-.015em;font-size:clamp(1.2rem,1.05rem + .6vw,1.5rem);font-weight:700;line-height:1.25}
.ov-lead{font-size:clamp(1.05rem,.98rem + .35vw,1.25rem);line-height:1.65}
.ov-container{width:100%;max-width:80rem;margin-inline:auto;padding-inline:1.25rem}
@media (min-width:768px){.ov-container{padding-inline:2rem}
.ov-text-gradient{color:#0000;background:linear-gradient(100deg,#8cba58,#693 45%,#3f7a2a);-webkit-background-clip:text;background-clip:text}
.ov-text-gradient-light{color:#0000;background:linear-gradient(100deg,#d9f0b8,#aed083 50%,#ffd873 110%);-webkit-background-clip:text;background-clip:text}
.ov-grid-bg{background-image:linear-gradient(#ffffff0b 1px,#0000 0),linear-gradient(90deg,#ffffff0b 1px,#0000 0);background-size:56px 56px;-webkit-mask-image:radial-gradient(#000 30%,#0000 75%);mask-image:radial-gradient(#000 30%,#0000 75%)}
.ov-grid-bg-light{background-image:linear-gradient(#0034730d 1px,#0000 0),linear-gradient(90deg,#0034730d 1px,#0000 0);background-size:48px 48px;-webkit-mask-image:radial-gradient(at top,#000 20%,#0000 70%);mask-image:radial-gradient(at top,#000 20%,#0000 70%)}
.ov-noise:after{content:"";pointer-events:none;opacity:.06;mix-blend-mode:overlay;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");position:absolute;inset:0}
.ov-glass{-webkit-backdrop-filter:blur(16px)saturate(140%);background:#ffffff14;border:1px solid #ffffff24}
.ov-card-hover{transition:transform .35s cubic-bezier(.22,1,.36,1),box-shadow .35s cubic-bezier(.22,1,.36,1),border-color .35s}
@media (hover:hover) and (prefers-reduced-motion:no-preference){.ov-card-hover:hover{transform:translateY(-4px);box-shadow:0 2px 6px -2px #0f172a0f,0 24px 48px -16px #0f172a2e}
.ov-reveal{transition:opacity .8s cubic-bezier(.22,1,.36,1),transform .8s cubic-bezier(.22,1,.36,1),filter .8s cubic-bezier(.22,1,.36,1);transition-delay:var(--ov-delay,0s)}
.js-ready .ov-reveal:not(.is-visible){opacity:0;filter:blur(6px);transform:translateY(28px)}
.js-ready .ov-reveal[data-dir=left]:not(.is-visible){transform:translate(-32px)}
.js-ready .ov-reveal[data-dir=right]:not(.is-visible){transform:translate(32px)}
.js-ready .ov-reveal[data-dir=scale]:not(.is-visible){transform:scale(.96)}
