=== style.css ===
@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  html {
    -webkit-text-size-adjust: 100%;
    -webkit-tap-highlight-color: transparent;
  }

  body {
    /* Sichere Bereiche auf Geräten mit Notch */
    padding-top: env(safe-area-inset-top);
    padding-bottom: env(safe-area-inset-bottom);
  }

  /* Eingaben nie kleiner als 16px — sonst zoomt iOS beim Fokus hinein. */
  input,
  select,
  textarea {
    font-size: max(16px, 1rem);
  }

  :focus-visible {
    @apply outline-none ring-2 ring-marke-500 ring-offset-2 ring-offset-white dark:ring-offset-slate-950;
  }
}

@layer components {
  /* Mindestgröße für Touch-Ziele mit Arbeitshandschuhen (NFA-023) */
  .tap {
    @apply min-h-tap min-w-tap;
  }

  .karte {
    @apply rounded-xl border border-slate-200 bg-white shadow-karte dark:border-slate-800 dark:bg-slate-900;
  }

  .knopf {
    @apply tap inline-flex items-center justify-center gap-2 rounded-xl px-4 text-base font-semibold
           transition active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-50;
  }

  .knopf-primaer {
    @apply knopf bg-marke-600 text-white hover:bg-marke-700;
  }

  .knopf-sekundaer {
    @apply knopf border border-slate-300 bg-white text-slate-700
           hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-200
           dark:hover:bg-slate-800;
  }

  .knopf-gefahr {
    @apply knopf bg-fehler text-white hover:bg-red-700;
  }

  .knopf-geist {
    @apply knopf text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800;
  }

  .feld {
    @apply tap w-full rounded-xl border border-slate-300 bg-white px-3 py-2 text-base text-slate-900
           placeholder:text-slate-400 focus:border-marke-500 focus:ring-0
           dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100 dark:placeholder:text-slate-500;
  }

  .beschriftung {
    @apply mb-1 block text-sm font-medium text-slate-600 dark:text-slate-300;
  }

  .abzeichen {
    @apply inline-flex items-center gap-1 rounded-full px-2.5 py-0.5 text-xs font-semibold;
  }

  .tabelle {
    @apply w-full border-collapse text-sm;
  }

  .tabelle th {
    @apply border-b border-slate-200 px-3 py-2 text-left font-semibold text-slate-600
           dark:border-slate-800 dark:text-slate-300;
  }

  .tabelle td {
    @apply border-b border-slate-100 px-3 py-2 align-top dark:border-slate-800/60;
  }
}

@layer utilities {
  .scrollbar-schmal::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }

  .scrollbar-schmal::-webkit-scrollbar-thumb {
    @apply rounded-full bg-slate-300 dark:bg-slate-700;
  }

  /* Horizontale Wischnavigation zwischen Prüfpunkten */
  .wisch {
    touch-action: pan-y;
  }
}

/* Leaflet-Grundlayout ohne das komplette Theme zu importieren */
.leaflet-container {
  @apply h-full w-full rounded-xl;
  background: #e2e8f0;
}

.dark .leaflet-container {
  background: #1e293b;
}

.dark .leaflet-tile {
  filter: brightness(0.75) contrast(1.05);
}
=== App.vue ===
<script setup lang="ts">
/**
 * Anwendungsrahmen mit drei Layouts (NFA-020 bis NFA-022):
 * - Smartphone: Kopfzeile + Tab-Leiste unten, Daumen erreicht alles
 * - Tablet:     wie Smartphone, aber breitere Inhaltsspalte
 * - Desktop:    dauerhafte Seitenleiste, Tab-Leiste entfällt
 *
 * Die Protokollausführung läuft im Vollbild ohne Rahmen.
 */
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'

import AppIcon from '@/components/AppIcon.vue'
import SyncIndikator from '@/components/SyncIndikator.vue'
import ToastBereich from '@/components/ToastBereich.vue'
import { SITZUNG_ABGELAUFEN } from '@/lib/api'
import { aufraeumen } from '@/lib/db'
import { aktualisierungVerfuegbar, aktualisierungVerschieben, jetztAktualisieren } from '@/lib/pwa'
import { useStammdaten } from '@/stores/stammdaten'
import { useSync } from '@/stores/sync'
import { useUi } from '@/stores/ui'

const route = useRoute()
const router = useRouter()
const stammdaten = useStammdaten()
const sync = useSync()
const ui = useUi()

const startfehler = ref<string | null>(null)
const bereit = ref(false)
const sitzungAbgelaufen = ref(false)

function neuAnmelden() {
  window.location.assign(`/login?redirect-to=${encodeURIComponent(window.location.pathname)}`)
}

const vollbild = computed(() => Boolean(route.meta.vollbild))

interface NavEintrag {
  name: string
  titel: string
  symbol: string
  rolle?: string
}

const alleEintraege: NavEintrag[] = [
  { name: 'dashboard', titel: 'Start', symbol: 'haus' },
  { name: 'anlagen', titel: 'Anlagen', symbol: 'anlage' },
  { name: 'protokolle', titel: 'Protokolle', symbol: 'protokoll' },
  { name: 'maengel', titel: 'Mängel', symbol: 'mangel' },
  { name: 'tagesberichte', titel: 'Berichte', symbol: 'bericht' },
  { name: 'karte', titel: 'Karte', symbol: 'karte' },
  { name: 'zeitfreigabe', titel: 'Zeitfreigabe', symbol: 'uhr', rolle: 'bauleiter' },
  { name: 'analysen', titel: 'Analysen', symbol: 'analyse', rolle: 'bauleiter' },
  { name: 'vorlagen', titel: 'Vorlagen', symbol: 'vorlage', rolle: 'projektleiter' },
  { name: 'einstellungen', titel: 'Einstellungen', symbol: 'zahnrad' },
]

/** Der Subunternehmer bekommt eine eigene Navigation — er hat mit dem Rest nichts zu tun. */
const portalEintraege: NavEintrag[] = [
  { name: 'portal', titel: 'Start', symbol: 'haus' },
  { name: 'portal-auftraege', titel: 'Aufträge', symbol: 'bericht' },
  { name: 'portal-personalmeldung', titel: 'Personal', symbol: 'person' },
  { name: 'portal-zeiten', titel: 'Zeiten', symbol: 'uhr' },
  { name: 'portal-material', titel: 'Material', symbol: 'plus' },
  { name: 'portal-meldung', titel: 'Meldung', symbol: 'warnung' },
]

function darfSehen(eintrag: NavEintrag): boolean {
  if (eintrag.rolle === 'bauleiter') return stammdaten.istBauleiter
  if (eintrag.rolle === 'projektleiter') return stammdaten.istProjektleiter
  return true
}

const navigation = computed(() =>
  stammdaten.istPortalnutzer ? portalEintraege : alleEintraege.filter(darfSehen),
)

/** Auf dem Smartphone bleiben fünf Tabs — der Rest liegt unter „Mehr“. */
const tableiste = computed(() => navigation.value.slice(0, 4))

const seitentitel = computed(() => (route.meta.titel as string) ?? 'Baudoku')

interface Schnellaktion {
  titel: string
  symbol: string
  ziel: string
  /** Kapitel 6.1: "Neuer Mangel - schnelle Mangelerfassung mit Kamera". */
  query?: Record<string, string>
}

const oekovoltAktionen: Schnellaktion[] = [
  { titel: 'Protokoll', symbol: 'protokoll', ziel: 'protokoll-neu' },
  { titel: 'Mangel mit Foto', symbol: 'kamera', ziel: 'mangel-neu', query: { kamera: '1' } },
  { titel: 'Mangel', symbol: 'mangel', ziel: 'mangel-neu' },
  { titel: 'Tagesbericht', symbol: 'bericht', ziel: 'tagesbericht-neu' },
]

const portalAktionen: Schnellaktion[] = [
  { titel: 'Material anfordern', symbol: 'plus', ziel: 'portal-material' },
  { titel: 'Behinderung melden', symbol: 'warnung', ziel: 'portal-meldung' },
]

const schnellaktionen = computed(() =>
  stammdaten.istPortalnutzer ? portalAktionen : oekovoltAktionen,
)
const aktionsmenueOffen = ref(false)

function schnellaktion(aktion: Schnellaktion) {
  aktionsmenueOffen.value = false
  void router.push({ name: aktion.ziel, query: aktion.query })
}

onMounted(async () => {
  window.addEventListener(SITZUNG_ABGELAUFEN, () => (sitzungAbgelaufen.value = true))
  sync.starten()
  try {
    await stammdaten.laden()
  } catch (fehler) {
    startfehler.value = (fehler as Error).message
  } finally {
    bereit.value = true
  }
  // Übertragene Fotos und gesichtete Konflikte nach einer Woche verwerfen.
  void aufraeumen().catch(() => undefined)
})
</script>

<template>
  <div class="flex h-full flex-col bg-slate-100 dark:bg-slate-950">
    <ToastBereich />

    <!-- Abgelaufene Sitzung: erfasste Daten bleiben lokal, nichts geht verloren -->
    <div
      v-if="sitzungAbgelaufen"
      class="fixed inset-x-0 top-0 z-40 flex items-center gap-3 bg-fehler px-4 py-3 text-sm text-white"
      role="alert"
    >
      <AppIcon name="warnung" :groesse="20" class="shrink-0" />
      <p class="flex-1">
        Die Anmeldung ist abgelaufen.
        <span class="block text-xs text-red-100">
          Erfasste Daten bleiben auf dem Gerät und werden nach dem Anmelden übertragen.
        </span>
      </p>
      <button class="shrink-0 rounded-lg bg-white px-3 py-1.5 text-xs font-semibold text-fehler"
              @click="neuAnmelden">
        Neu anmelden
      </button>
    </div>

    <!-- Neue Fassung verfügbar — der Benutzer entscheidet, wann geladen wird -->
    <div
      v-if="aktualisierungVerfuegbar"
      class="fixed inset-x-0 bottom-0 z-40 flex items-center gap-3 border-t border-marke-600
             bg-marke-700 px-4 py-3 text-sm text-white desktop:inset-x-auto desktop:bottom-4
             desktop:right-4 desktop:max-w-md desktop:rounded-xl desktop:border"
      role="status"
    >
      <AppIcon name="pfeilUnten" :groesse="20" class="shrink-0" />
      <p class="flex-1">
        Eine neue Fassung steht bereit.
        <span class="block text-xs text-marke-100">
          Laufende Erfassungen sind lokal gespeichert und gehen nicht verloren.
        </span>
      </p>
      <button class="shrink-0 rounded-lg px-3 py-1.5 text-xs font-semibold text-marke-100
                     hover:bg-marke-600"
              @click="aktualisierungVerschieben">
        Später
      </button>
      <button class="shrink-0 rounded-lg bg-white px-3 py-1.5 text-xs font-semibold text-marke-700"
              @click="jetztAktualisieren">
        Aktualisieren
      </button>
    </div>

    <!-- Startbildschirm, solange die Stammdaten geladen werden -->
    <div v-if="!bereit" class="flex h-full flex-col items-center justify-center gap-4">
      <AppIcon name="blitz" :groesse="48" class="animate-pulse text-marke-600" />
      <p class="text-sm text-slate-500">Baudoku wird geladen …</p>
    </div>

    <template v-else-if="vollbild">
      <RouterView />
    </template>

    <template v-else>
      <div class="flex h-full min-h-0">
        <!-- Seitenleiste ab Desktop (NFA-022) -->
        <aside
          class="hidden w-60 shrink-0 flex-col border-r border-slate-200 bg-white desktop:flex
                 dark:border-slate-800 dark:bg-slate-900"
        >
