/** Neutralachse der Marke: leicht blaustichiges Grau für Text und Ränder. */
const ink = {
  50: '#f7f8fa',
  100: '#eef0f4',
  200: '#dfe3ea',
  300: '#c4cad5',
  400: '#97a0b0',
  500: '#6b7486',
  600: '#4e5667',
  700: '#394050',
  800: '#252b37',
  900: '#151a24',
}

/** Ruhiger Papierton für Flächen, die sich von Weiß absetzen sollen. */
const sand = {
  50: '#fbfaf6',
  100: '#f5f3ea',
}

/**
 * Die App war auf Tailwinds `slate` gebaut (gut 600 Stellen in Ansichten und
 * Komponenten). Statt jede davon anzufassen, zeigt `slate` auf die Neutralen
 * der Marke: die hellen Stufen auf `ink`, die dunklen auf Navy-Töne. So wird
 * das dunkle Design marineblau statt grau (NFA-025 bleibt erhalten).
 *
 * Neu geschriebene Ansichten verwenden bitte direkt `ink-*` und `navy-*`.
 */
const slate = {
  50: ink[50],
  100: ink[100],
  200: ink[200],
  300: ink[300],
  400: ink[400],
  500: ink[500],
  600: ink[600],
  700: '#223a56',
  800: '#132840',
  900: '#0a1c33',
  950: navy[950],
}

export default {
  content: ['./index.html', './src/**/*.{vue,ts}'],
  darkMode: 'class',
  theme: {
    extend: {
      colors: {
        ov,
        navy,
        ink,
        sand,
        slate,
        /**
         * Altbestand: `marke-*` bleibt als Alias auf das Laubgrün bestehen,
         * damit vorhandene Klassen ohne Umschreiben auf die Markenfarbe
         * umschwenken. Neue Ansichten schreiben `ov-*`.
         */
        marke: ov,
        // Statusfarben (identisch zu utils/jinja.py, damit PDF und UI übereinstimmen)
        ok: ov[600],
        warnung: '#f59e0b',
        fehler: '#dc2626',
        offen: ink[400],
      },
      fontFamily: {
        sans: ['Inter Variable', 'Inter', 'system-ui', '-apple-system', 'Segoe UI', 'sans-serif'],
        // Überschriften und Kennzahlen — wie auf der Website
        display: ['Manrope Variable', 'Manrope', 'Inter Variable', 'system-ui', 'sans-serif'],
      },
      spacing: {
        // Mindestgröße für Touch-Ziele mit Arbeitshandschuhen (NFA-023)
        tap: '44px',
      },
      maxWidth: {
        feld: '52rem',
      },
      borderRadius: {
        '4xl': '2rem',
