.pf { font-family: "Inter", "Helvetica Neue", Arial, sans-serif; font-size: 9.5pt; color: #0f172a; }
.pf h1 { font-size: 16pt; margin: 0 0 2mm; }
.pf h2 { font-size: 11pt; margin: 6mm 0 2mm; padding-bottom: 1mm;
         border-bottom: 1.5pt solid #0f172a; text-transform: uppercase; letter-spacing: .04em; }
.pf .kopf { display: flex; justify-content: space-between; align-items: flex-start;
            border-bottom: 2pt solid #0f172a; padding-bottom: 3mm; margin-bottom: 4mm; }
.pf .kopf .firma { text-align: right; font-size: 8pt; color: #475569; line-height: 1.45; }
.pf .kopf img { max-height: 16mm; }
.pf table { width: 100%; border-collapse: collapse; }
.pf td, .pf th { border: .5pt solid #cbd5e1; padding: 1.4mm 2mm; vertical-align: top; }
.pf th { background: #f1f5f9; text-align: left; font-weight: 600; }
.pf .stamm td { border: none; padding: .8mm 0; }
.pf .stamm td.l { color: #64748b; width: 32mm; }
.pf .badge { display: inline-block; padding: .4mm 2mm; border-radius: 2mm;
             color: #fff; font-size: 7.5pt; font-weight: 600; }
.pf .fotos { display: flex; flex-wrap: wrap; gap: 2mm; margin-top: 2mm; }
.pf .foto { width: 52mm; }
.pf .foto img { width: 100%; border: .5pt solid #cbd5e1; border-radius: 1mm; }
.pf .foto .bu { font-size: 7pt; color: #475569; margin-top: .6mm; }
.pf .sig { display: flex; gap: 8mm; margin-top: 6mm; }
.pf .sig .feld { flex: 1; }
.pf .sig img { height: 18mm; display: block; }
.pf .sig .linie { border-top: .5pt solid #0f172a; margin-top: 1mm; padding-top: 1mm;
                  font-size: 8pt; color: #475569; }
.pf .fuss { margin-top: 8mm; padding-top: 2mm; border-top: .5pt solid #cbd5e1;
            font-size: 7.5pt; color: #64748b; }
.pf .hinweis { font-size: 8pt; color: #64748b; font-style: italic; }
.pf tr { page-break-inside: avoid; }

