- "html": "<div class="pf">

<div class="kopf">
	<div>
		<h1>{{ doc.vorlage_typ }}-Protokoll</h1>
		<div class="hinweis">{{ frappe.db.get_value('Checklistenvorlage', doc.vorlage, 'titel') }} (Rev. {{ doc.vorlage_revision }})</div>
	</div>
	<div class="firma">
		<b>OEKOVOLT Solartechnik GmbH</b><br>
		Gewerbegebiet 10<br>
		5121 Ostermiething, Oesterreich<br>
		Dokument {{ doc.name }}
	</div>
</div>

<table class="stamm">
	<tr>
		<td class="l">Anlage</td>
		<td><b>{{ frappe.db.get_value("PV Anlage", doc.anlage, "anlage_name") }}</b> ({{ doc.anlage }})</td>
		<td class="l">Pruefer</td>
		<td>{{ frappe.db.get_value("Employee", doc.pruefer, "employee_name") }}</td>
	</tr>
	<tr>
		<td class="l">Auftraggeber</td><td>{{ doc.customer or "-" }}</td>
		<td class="l">Beginn</td><td>{{ frappe.format(doc.pruef_datum, {"fieldtype": "Datetime"}) }}</td>
	</tr>
	<tr>
		<td class="l">Projekt</td><td>{{ doc.project or "-" }}</td>
		<td class="l">Ende</td><td>{{ frappe.format(doc.abschluss_datum, {"fieldtype": "Datetime"}) }}</td>
	</tr>
	<tr>
		<td class="l">Wetter</td><td>{{ doc.wetter or "-" }}{% if doc.temperatur %}, {{ doc.temperatur }} C{% endif %}</td>
		<td class="l">Messmittel</td><td>{{ doc.messmittel or "-" }}</td>
	</tr>
	<tr>
		<td class="l">Anwesend</td><td colspan="3">{{ doc.anwesende_personen or "-" }}</td>
	</tr>
	{% if doc.gps_koordinaten %}
	<tr><td class="l">GPS</td><td colspan="3">{{ doc.gps_koordinaten }}</td></tr>
	{% endif %}
</table>

{% for gruppe in gruppiere_ergebnisse(doc.ergebnisse) %}
<h2>{{ gruppe.sektion }}</h2>
<table>
	<tr><th style="width:12mm">Nr.</th><th>Pruefpunkt</th><th style="width:38mm">Ergebnis</th>
		<th style="width:20mm">Status</th></tr>
	{% for z in gruppe.zeilen %}
	<tr>
		<td>{{ z.nummer or "" }}</td>
		<td>
			{{ z.titel }}
			{% if z.bemerkung %}<br><span class="hinweis">{{ z.bemerkung }}</span>{% endif %}
			{% if z.plausi_meldung and z.status in ("Warnung", "Fehler") %}
				<br><span class="hinweis">{{ z.plausi_meldung }}</span>
			{% endif %}
			{% if z.uebersteuert %}
				<br><span class="hinweis">Uebersteuert: {{ z.uebersteuerung_grund }}</span>
			{% endif %}
			{% if z.mangel %}<br><b>Mangel {{ z.mangel }}</b>{% endif %}
			{% if z.fotos %}
			<div class="fotos">
				{% for foto in z.fotos %}
				<div class="foto">
					<img src="{{ bild_daten(foto.bild) }}">
					<div class="bu">{{ foto.beschriftung or "" }}
						{{ frappe.format(foto.aufgenommen_am, {"fieldtype": "Datetime"}) }}</div>
				</div>
				{% endfor %}
			</div>
			{% endif %}
		</td>
		<td>
			{%- if z.feldtyp == "Bewertung" -%}{{ z.bewertung or "-" }}
			{%- elif z.feldtyp == "Zahlenwert" -%}{{ z.wert_zahl }} {{ z.einheit or "" }}
			{%- elif z.feldtyp == "Ja-Nein" -%}{{ "Ja" if z.wert_ja_nein else "Nein" }}
			{%- elif z.feldtyp == "Datum" -%}{{ frappe.format(z.wert_datum, {"fieldtype": "Date"}) }}
			{%- elif z.feldtyp == "Foto" -%}{{ "siehe Foto" if z.fotos else "-" }}
			{%- else -%}{{ z.wert_text or "-" }}{%- endif -%}
		</td>
		<td><span class="badge" style="background:{{ status_farbe(z.status) }}">{{ z.status }}</span></td>
	</tr>
	{% endfor %}
</table>
{% endfor %}

{% if doc.messdaten %}
<h2>String-Messdaten</h2>
<table>
	<tr><th>String</th><th>WR / MPPT</th><th>Module</th><th>Uoc (V)</th><th>Isc (A)</th>
		<th>Riso (kOhm)</th><th>Status</th></tr>
	{% for m in doc.messdaten %}
	<tr>
		<td>{{ m.string_nr }}</td><td>{{ m.wechselrichter or "-" }}</td><td>{{ m.anzahl_module }}</td>
		<td>{{ m.uoc }}</td><td>{{ m.isc }}</td><td>{{ m.riso }}</td>
		<td><span class="badge" style="background:{{ status_farbe(m.status) }}">{{ m.status }}</span></td>
	</tr>
	{% if m.plausi_meldung and m.status != "OK" %}
	<tr><td colspan="7" class="hinweis">{{ m.plausi_meldung }}
		{% if m.uebersteuert %} - uebersteuert: {{ m.uebersteuerung_grund }}{% endif %}</td></tr>
	{% endif %}
	{% endfor %}
</table>
{% endif %}

<h2>Gesamtbewertung</h2>
<p><span class="badge" style="background:{{ status_farbe(doc.gesamtbewertung) }}; font-size:10pt">
	{{ doc.gesamtbewertung or "ohne Bewertung" }}</span></p>
{% if doc.zusammenfassung %}<div>{{ doc.zusammenfassung }}</div>{% endif %}
<p class="hinweis">{{ doc.anzahl_erledigt }} von {{ doc.anzahl_pruefpunkte }} Pruefpunkten erfasst,
	{{ doc.anzahl_maengel or 0 }} Maengel dokumentiert.</p>

{% if doc.unterschriften %}
<h2>Unterschriften</h2>
<div class="sig">
	{% for u in doc.unterschriften %}
	<div class="feld">
		<img src="{{ u.signatur }}">
		<div class="linie">
			{{ u.name_unterzeichner }} ({{ u.rolle }})<br>
			{{ frappe.format(u.unterzeichnet_am, {"fieldtype": "Datetime"}) }}
			{% if u.ip_adresse %}<br>IP {{ u.ip_adresse }}{% endif %}
		</div>
	</div>
	{% endfor %}
</div>
{% endif %}

<div class="fuss">
	Erstellt mit OEKOVOLT Baudoku - {{ frappe.utils.now() }}.
	Dieses Protokoll wurde digital erfasst und ist ohne Unterschrift nur als Entwurf gueltig.
</div>
</div>
",

