import io
p = 'style.css'
s = io.open(p, encoding='utf-8').read()

# Ankreuzfelder und Auswahlknoepfe in der Hausfarbe
alt = """  /* Eingaben nie kleiner als 16px — sonst zoomt iOS beim Fokus hinein. */"""
neu = """  /* Ankreuzfelder und Auswahlknöpfe haken in der Hausfarbe ab. */
  input[type='checkbox'],
  input[type='radio'] {
    accent-color: theme('colors.ov.600');
  }

  /* Eingaben nie kleiner als 16px — sonst zoomt iOS beim Fokus hinein. */"""
assert s.count(alt) == 1
s = s.replace(alt, neu)

# Kippschalter fuer Ja/Nein-Einstellungen
alt2 = """  .beschriftung {"""
neu2 = """  /**
   * Kippschalter aus einem echten Ankreuzfeld: Tastatur, Screenreader und
   * `v-model` funktionieren unveraendert, nur die Darstellung ist ersetzt.
   */
  .schalter {
    @apply relative h-6 w-11 shrink-0 cursor-pointer appearance-none rounded-full bg-ink-300
           transition-colors dark:bg-white/20;
  }

  .schalter:checked {
    @apply bg-ov-600;
  }

  .schalter::after {
    content: '';
    @apply absolute left-0.5 top-0.5 h-5 w-5 rounded-full bg-white shadow transition-transform;
  }

  .schalter:checked::after {
    @apply translate-x-5;
  }

  .beschriftung {"""
assert s.count(alt2) == 1
s = s.replace(alt2, neu2)
io.open(p, 'w', encoding='utf-8').write(s)

p = 'views/EinstellungenView.vue'
s = io.open(p, encoding='utf-8').read()
alt3 = '<input v-model="ui.dunkel" type="checkbox" class="h-6 w-11" />'
assert s.count(alt3) == 1
s = s.replace(alt3, '<input v-model="ui.dunkel" type="checkbox" class="schalter" />')
io.open(p, 'w', encoding='utf-8').write(s)
print('Kippschalter und Hausfarbe fuer Ankreuzfelder ergaenzt')
