1	/**
2	 * Grundgestaltung der Baudoku im ÖKOVOLT-Corporate-Design.
3	 *
4	 * Die Formensprache folgt der Website: Pillen statt Kästchen, Ringe statt
5	 * Rahmen, großzügige Rundungen, Flächen in Weiß und Sand auf Ink-Neutralen.
6	 * Feldtauglichkeit geht dabei vor Effekt — Touch-Ziele bleiben bei 44 px
7	 * (NFA-023), Kontraste bleiben sonnentauglich, Bewegung bleibt sparsam.
8	 */
9	@import './assets/schriften.css';
10	
11	@tailwind base;
12	@tailwind components;
13	@tailwind utilities;
14	
15	@layer base {
16	  html {
17	    -webkit-text-size-adjust: 100%;
18	    -webkit-tap-highlight-color: transparent;
19	  }
20	
21	  body {
22	    /* Sichere Bereiche auf Geräten mit Notch */
23	    padding-top: env(safe-area-inset-top);
24	    padding-bottom: env(safe-area-inset-bottom);
25	    @apply font-sans;
26	  }
27	
28	  /* Überschriften in der Hausschrift, eng gesetzt wie auf der Website. */
29	  h1,
30	  h2,
31	  h3 {
32	    @apply font-display font-bold tracking-tight;
33	  }
34	
35	  /* Ankreuzfelder und Auswahlknöpfe haken in der Hausfarbe ab. */
36	  input[type='checkbox'],
37	  input[type='radio'] {
38	    accent-color: theme('colors.ov.600');
39	  }
40	
41	  /* Eingaben nie kleiner als 16px — sonst zoomt iOS beim Fokus hinein. */
42	  input,
43	  select,
44	  textarea {
45	    font-size: max(16px, 1rem);
46	  }
47	
48	  :focus-visible {
49	    @apply outline-none ring-2 ring-ov-500 ring-offset-2 ring-offset-white dark:ring-offset-navy-950;
50	  }
51	}
52	
53	@layer components {
54	  /* Mindestgröße für Touch-Ziele mit Arbeitshandschuhen (NFA-023) */
55	  .tap {
56	    @apply min-h-tap min-w-tap;
57	  }
58	
59	  /**
60	   * Flächen tragen ihre Kante als Ring, nicht als Rahmen: der Ring liegt außen
61	   * auf und verschiebt dadurch kein Innenmaß, wenn eine Karte aktiv wird.
62	   */
63	  .karte {
64	    @apply rounded-2xl bg-white shadow-karte ring-1 ring-ink-200/70
65	           dark:bg-slate-900 dark:shadow-none dark:ring-white/10;
66	  }
67	
68	  /* Karte, die auf Tippen/Zeigen reagiert — für Listeneinträge mit Ziel. */
69	  .karte-aktiv {
70	    @apply karte transition duration-300 hover:ring-ov-200 active:scale-[0.995]
71	           dark:hover:ring-ov-500/40;
72	  }
73	
74	  @media (hover: hover) and (prefers-reduced-motion: no-preference) {
75	    .karte-aktiv:hover {
76	      @apply -translate-y-0.5 shadow-schwebe;
77	    }
78	  }
79	
80	  /* Ruhige Fläche für eingebettete Abschnitte innerhalb einer Karte. */
81	  .flaeche {
82	    @apply rounded-xl bg-sand-50 ring-1 ring-ink-200/60 dark:bg-white/5 dark:ring-white/10;
83	  }
84	
85	  .knopf {
86	    @apply tap inline-flex items-center justify-center gap-2 rounded-full px-5 text-base font-semibold
87	           transition active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-50;
88	  }
89	
90	  .knopf-primaer {
91	    @apply knopf bg-ov-600 text-white shadow-sm hover:bg-ov-700;
92	  }
93	
