95	    @apply knopf bg-white text-ink-900 ring-1 ring-inset ring-ink-200
96	           hover:bg-ink-50 hover:text-ov-700
97	           dark:bg-white/5 dark:text-ink-100 dark:ring-white/15 dark:hover:bg-white/10;
98	  }
99	
100	  .knopf-gefahr {
101	    @apply knopf bg-fehler text-white shadow-sm hover:bg-red-700;
102	  }
103	
104	  .knopf-geist {
105	    @apply knopf text-ink-600 hover:bg-ink-100 hover:text-ov-700
106	           dark:text-ink-300 dark:hover:bg-white/10 dark:hover:text-ov-300;
107	  }
108	
109	  /**
110	   * Eingabefelder mit Innenring: im Ruhezustand zurückhaltend, im Fokus in
111	   * Markengrün und zwei Pixel stark — auf dem Dach bei Sonne noch erkennbar.
112	   */
