115	           ring-ink-200 transition placeholder:text-ink-400
116	           focus:ring-2 focus:ring-inset focus:ring-ov-500
117	           dark:bg-white/5 dark:text-ink-50 dark:ring-white/15 dark:placeholder:text-ink-500;
118	  }
119	
120	  /**
121	   * Kippschalter aus einem echten Ankreuzfeld: Tastatur, Screenreader und
122	   * `v-model` funktionieren unveraendert, nur die Darstellung ist ersetzt.
