136	  }
137	
138	  .schalter:checked::after {
139	    @apply translate-x-5;
140	  }
141	
142	  .beschriftung {
143	    @apply mb-1.5 block text-sm font-semibold text-ink-700 dark:text-ink-300;
144	  }
145	
146	  /* Kleine Zeile über einer Überschrift — das Eyebrow-Muster der Website. */
147	  .uebertitel {
148	    @apply text-[11px] font-bold uppercase tracking-[0.14em] text-ov-700 dark:text-ov-300;
149	  }
150	
151	  .abzeichen {
152	    @apply inline-flex items-center gap-1 rounded-full px-2.5 py-0.5 text-xs font-semibold;
153	  }
154	
155	  .tabelle {
156	    @apply w-full border-collapse text-sm;
157	  }
158	
159	  .tabelle th {
160	    @apply border-b border-ink-200 px-3 py-2 text-left text-[11px] font-bold uppercase
161	           tracking-wider text-ink-500 dark:border-white/10 dark:text-ink-400;
162	  }
163	
