describe('tageText', () => {
  it('setzt die Einzahl bei genau einem Tag', () => {
    expect(tageText(1)).toBe('1 Tag')
  })

  it('setzt die Mehrzahl ab zwei Tagen', () => {
    expect(tageText(2)).toBe('2 Tage')
    expect(tageText(30)).toBe('30 Tage')
  })

  it('nennt null Tage in der Mehrzahl', () => {
    expect(tageText(0)).toBe('0 Tage')
  })

  /**
   * Überfälliges kommt als negative Zahl herein ("vor 2 Tagen fällig
   * gewesen"). Das Vorzeichen gehört nicht in den Text — davor steht dann
   * "überfällig".
   */
  it('lässt das Vorzeichen überfälliger Fristen weg', () => {
    expect(tageText(-1)).toBe('1 Tag')
    expect(tageText(-5)).toBe('5 Tage')
  })
})

