test.describe('Zeitfreigabe (Bauleiter)', () => {
  test('hebt auffällige Arbeitstage hervor und gibt ausgewählte frei', async ({ page }) => {
    await appOeffnen(page, '/baudoku/zeitfreigabe')

    await expect(page.getByRole('heading', { name: 'Arbeitszeiten freigeben' })).toBeVisible()

    // Was arbeitsrechtlich auffällt, darf nicht ungeprüft durchlaufen
    await expect(page.getByText('über Tagesgrenze')).toBeVisible()
    await expect(page.getByText(/\d+ auffällig/)).toBeVisible()

    await page.getByRole('checkbox', { name: 'alle' }).check()
    await expect(page.getByRole('button', { name: 'Freigeben' })).toBeVisible()
    await page.getByRole('button', { name: 'Freigeben' }).click()

    await expect(page.getByText('Alle erfassten Arbeitstage sind bearbeitet.')).toBeVisible()
  })
})
